<?php
if(!defined('IN_LAYOUT')||!in_array($role??'',['admin','super_admin'],true)){http_response_code(403);return;}
require_once __DIR__.'/../classes/StaffActivity.php';
$activityEscape=static fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
try{$activity=(new StaffActivity($db))->history($_GET,$role);}catch(InvalidArgumentException $e){echo '<p class="st-error" role="alert">'.$activityEscape($e->getMessage()).'</p>';$_GET['activity_from']='';$_GET['activity_to']='';$activity=(new StaffActivity($db))->history($_GET,$role);}
$af=$activity['filters'];$activityURL=static fn($changes=[])=>'layout.php?'.http_build_query(array_merge(['page'=>'system_settings','section'=>'activity'],$af,$changes));
$kindLabels=['action'=>'Saved changes & posts','access'=>'Record access','print'=>'Print preparation','export'=>'Report exports','profile'=>'Profile & security changes'];
?>
<section class="st-activity" aria-labelledby="staffActivityTitle"><header class="st-heading"><div><p class="st-eyebrow">ACCOUNTABILITY & ACTIVITY</p><h2 id="staffActivityTitle">Guidance staff activity</h2><p>Review guidance counselor and advocate actions across the office workspace.</p></div><span class="st-count"><?=number_format($activity['total'])?> matching records</span></header>
<p class="st-help">Record access, print preparation, exports, saved changes and posts by guidance counselors and advocates. General page visits and account sign-ins are excluded.</p>
<details class="st-filters"><summary>Activity filters <small>Staff member, role, action and dates</small></summary><form method="get" action="layout.php" data-wf-ready="1"><input type="hidden" name="page" value="system_settings"><input type="hidden" name="section" value="activity">
<label>Staff role<select name="staff_role"><option value="">All staff roles</option><?php foreach(StaffActivity::ROLES as $v=>$label):?><option value="<?=$v?>" <?=$af['staff_role']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label>
<label>Staff member<select name="staff_user"><option value="">All staff</option><?php foreach($activity['people'] as $person):?><option value="<?=(int)$person['id']?>" <?=$af['staff_user']===(string)$person['id']?'selected':''?>><?=$activityEscape(trim($person['first_name'].' '.$person['last_name']))?> — <?=$activityEscape(StaffActivity::ROLES[$person['role']])?></option><?php endforeach;?></select></label>
<label>Activity<select name="activity_kind"><option value="">All activities</option><?php foreach($kindLabels as $v=>$label):?><option value="<?=$v?>" <?=$af['activity_kind']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label>
<label>Workspace area<select name="activity_module"><option value="">All areas</option><?php foreach(StaffActivity::MODULES as $v=>$label):?><option value="<?=$v?>" <?=$af['activity_module']===$v?'selected':''?>><?=$activityEscape($label)?></option><?php endforeach;?></select></label>
<label>From date<input type="date" name="activity_from" value="<?=$activityEscape($af['activity_from'])?>"></label><label>To date<input type="date" name="activity_to" value="<?=$activityEscape($af['activity_to'])?>"></label><div class="st-actions"><button type="submit">Apply filters</button><a href="layout.php?page=system_settings&amp;section=activity">Clear filters</a></div></form></details>
<div class="st-table-wrap"><table class="st-table" data-cw-no-cards><thead><tr><th>Date & time</th><th>Staff member</th><th>Role</th><th>Activity</th><th>Workspace area</th><th>What happened</th><th>IP address</th></tr></thead><tbody>
<?php foreach($activity['rows'] as $entry):?><tr data-staff-log="<?=(int)$entry['id']?>"><td><strong><?=$activityEscape(date('M j, Y',strtotime($entry['created_at'])))?></strong><small><?=$activityEscape(date('g:i:s A',strtotime($entry['created_at'])))?></small></td><td><?=$activityEscape(trim(($entry['first_name']??'Former staff').' '.($entry['last_name']??'')))?></td><td><span class="st-role" data-role="<?=$activityEscape($entry['actor_role'])?>"><?=$activityEscape(StaffActivity::ROLES[$entry['actor_role']]??'Staff')?></span></td><td><?=$activityEscape($kindLabels[$entry['activity_kind']]??'Activity')?></td><td><?=$activityEscape(StaffActivity::MODULES[$entry['module']]??($entry['activity_kind']==='export'?'Reports':($entry['activity_kind']==='profile'?'My profile':'Account access')))?></td><td><?=$activityEscape($entry['summary'])?></td><td><?=$activityEscape($entry['ip_address']??'Not recorded')?><?php if(SystemLogger::isLoopbackAddress($entry['ip_address']??'')):?><small>This computer</small><?php endif;?></td></tr><?php endforeach;?>
<?php if(!$activity['rows']):?><tr><td colspan="7" class="st-empty"><strong>No matching staff activity</strong><p>Try another role, staff member or date range.</p></td></tr><?php endif;?></tbody></table></div>
<footer class="st-pagination"><span>Showing <?=$activity['total']?($activity['page']-1)*10+1:0?>–<?=min($activity['page']*10,$activity['total'])?> of <?=$activity['total']?> · 10 per page</span><nav aria-label="Staff activity pages"><?php if($activity['page']>1):?><a href="<?=$activityEscape($activityURL(['activity_page'=>$activity['page']-1]))?>">Previous</a><?php endif;?><span>Page <?=$activity['page']?> of <?=$activity['pages']?></span><?php if($activity['page']<$activity['pages']):?><a href="<?=$activityEscape($activityURL(['activity_page'=>$activity['page']+1]))?>">Next</a><?php endif;?></nav></footer><p class="st-help">Activity summaries exclude counseling notes, student answers, passwords and other submitted content. Roles on new events reflect the role at the time of the action; older events use the account’s current role.</p></section>
